tool_input.content:
const fs = require('fs');
const html = fs.readFileSync('/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/u33/game.html','utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
if (!m){ console.log('NO SCRIPT'); process.exit(1); }
const js = m[1];
try { new Function(js); console.log('SYNTAX_OK (full script parses)'); }
catch(e){ console.log('SYNTAX FAIL:', e.message); process.exit(1); }
const core = js.split('   UI LAYER')[0].replace(/\/\* =+\s*$/,'');
let api;
try {
  const run = new Function(core + '\n;return {runTestsCore,runBenchmarkCore,runWinCheck,newGame,hashState,loadString,saveString};');
  api = run();
} catch(e){ console.log('CORE EVAL FAIL:', e.message); process.exit(1); }
const tests = api.runTestsCore();
for (const t of tests) console.log((t.pass?'PASS':'FAIL')+'  '+t.name+(t.pass?'':'  :: '+t.detail));
console.log(tests.filter(t=>t.pass).length+'/'+tests.length+' passed');
const a = api.runBenchmarkCore(1337,200), b = api.runBenchmarkCore(1337,200);
console.log('bench hash1',a.hash,'hash2',b.hash,'deterministic:',a.hash===b.hash);
console.log('bench stats: turn',a.turnsRun,'pop',a.pop,'research',a.research,'buildings',a.buildings,'morale',a.avgMorale);
console.log('bench res:',JSON.stringify(a.res));
console.log('wincheck 1337:',JSON.stringify(api.runWinCheck(1337)));
console.log('wincheck 42:',JSON.stringify(api.runWinCheck(42)));
console.log('wincheck 7:',JSON.stringify(api.runWinCheck(7)));
